// Round 6 (TR-T-CSRF Secure flag, F-L8 release origin, F-M2 trusted proxy). Local TLS material lives only under
// .local/tls/ (git-ignored, generated by ops/local-tls.sh): a locally generated CA that is NOT installed system-wide,
// a 127.0.0.1/localhost server certificate, the proxy secret and the login device-cookie key. Nothing here is printed.
import fs from 'node:fs';import path from 'node:path';import {timingSafeEqual} from 'node:crypto';
export const TLS_DIR=()=>path.resolve(process.env.ALDER_TLS_DIR||'.local/tls');
const read=(f:string)=>fs.readFileSync(path.join(TLS_DIR(),f));
export const tlsAvailable=()=>['server.key','server.pem','ca.pem'].every(f=>fs.existsSync(path.join(TLS_DIR(),f)));
export const serverTls=()=>({key:read('server.key'),cert:read('server.pem')});
export const caPem=()=>read('ca.pem');
// The only browser origins allowed to log in and mutate: the dev UI and the built-bundle release, both HTTPS.
export const PUBLIC_ORIGINS:readonly string[]=(process.env.ALDER_PUBLIC_ORIGINS||'https://127.0.0.1:5103,https://127.0.0.1:5113').split(',').map(s=>s.trim()).filter(Boolean);
export const isAllowedOrigin=(o:unknown)=>typeof o==='string'&&PUBLIC_ORIGINS.includes(o);
let proxySecretCache:Buffer|null|undefined;
export function proxySecret():Buffer|null{if(proxySecretCache===undefined){try{proxySecretCache=Buffer.from(read('proxy-secret').toString('utf8').trim());}catch{proxySecretCache=null;}}return proxySecretCache;}
// True only when the request carries the shared secret that only the known front proxies (Vite dev server and the
// release server) add. Anything else on loopback is keyed by its socket address and its X-Forwarded-For is ignored.
export function fromTrustedProxy(headers:any){const s=proxySecret();const h=headers?.['x-alder-proxy'];if(!s||typeof h!=='string')return false;const b=Buffer.from(h);return b.length===s.length&&timingSafeEqual(b,s);}
let deviceKeyCache:Buffer|undefined;
export function deviceKey():Buffer{if(!deviceKeyCache){let value:string;try{value=read('device-key').toString('utf8').trim();}catch{if(!process.env.ALDER_DEVICE_KEY_TEST)throw Error('DEVICE_KEY_REQUIRED');value=process.env.ALDER_DEVICE_KEY_TEST;}if(!/^[0-9a-f]{64}$/i.test(value))throw Error('DEVICE_KEY_INVALID');deviceKeyCache=Buffer.from(value,'hex');}return deviceKeyCache;}
